export type ParsedPublicSettleSlotInstruction<
  TProgram extends string = typeof AGARI_PRIVATE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Permissionless: the proceeds stay in the slot whoever cranks it. */
    caller: TAccountMetas[0];
    deskAccount: TAccountMetas[1];
    slot: TAccountMetas[2];
    custody: TAccountMetas[3];
    seat: TAccountMetas[4];
    eventsProgram: TAccountMetas[5];
    eventsConfig: TAccountMetas[6];
    series: TAccountMetas[7];
    market: TAccountMetas[8];
    ledger: TAccountMetas[9];
    mvault: TAccountMetas[10];
    collateralMint: TAccountMetas[11];
    tokenProgram: TAccountMetas[12];
    eventsEventAuthority: TAccountMetas[13];
  };
  data: PublicSettleSlotInstructionData;
};

export function parsePublicSettleSlotInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedPublicSettleSlotInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 14) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 14,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      caller: getNextAccount(),
      deskAccount: getNextAccount(),
      slot: getNextAccount(),
      custody: getNextAccount(),
      seat: getNextAccount(),
      eventsProgram: getNextAccount(),
      eventsConfig: getNextAccount(),
      series: getNextAccount(),
      market: getNextAccount(),
      ledger: getNextAccount(),
      mvault: getNextAccount(),
      collateralMint: getNextAccount(),
      tokenProgram: getNextAccount(),
      eventsEventAuthority: getNextAccount(),
    },
    data: getPublicSettleSlotInstructionDataDecoder().decode(instruction.data),
  };
}
